import itertools

def solve_small(N, M):
    # State: (x1, ..., xN)
    # A state is safe if for all k, there is s in {1, -1} such that the next state is safe.
    # We'll use the iterative removal method.

    states = list(itertools.product(range(1, M + 1), repeat=N))
    safe = {s: True for s in states}

    while True:
        changed = False
        for s in states:
            if not safe[s]:
                continue

            # Check if s is safe
            is_s_safe = True
            for k in range(1, N):
                # Bob chooses k
                # Alice must have an s_choice in {1, -1}
                can_alice_stay_safe = False
                for s_choice in [1, -1]:
                    # New state
                    new_s = list(s)
                    for i in range(k):
                        new_s[i] += s_choice
                    for i in range(k, N):
                        new_s[i] -= s_choice

                    new_s = tuple(new_s)

                    # Check if new_s is in safe and has all elements >= 1
                    if all(x >= 1 for x in new_s) and \
                       all(x <= M for x in new_s) and \
                       safe.get(new_s, False):
                        can_alice_stay_safe = True
                        break

                if not can_alice_stay_safe:
                    is_s_safe = False
                    break

            if not is_s_safe:
                safe[s] = False
                changed = True
        if not changed:
            break

    min_n = float('inf')
    for s, is_safe in safe.items():
        if is_safe:
            min_n = min(min_n, sum(s))

    return min_n

for N in range(2, 6):
    print(f"N={N}, min_n={solve_small(N, 6)}")

